-- ============================================================================
-- Migration 009: Expand Quiz Questions & Enable Randomization Pool
-- Seeds 30 comprehensive questions each for JavaScript, React, Python, SQL,
-- and System Design into public.quiz_questions.
-- Safe to re-run (idempotent with ON CONFLICT / WHERE NOT EXISTS checks)
-- ============================================================================

-- ─── JAVASCRIPT QUESTIONS (30 questions) ───
WITH quiz_target AS (SELECT id FROM public.quizzes WHERE skill_name = 'JavaScript' LIMIT 1)
INSERT INTO public.quiz_questions (quiz_id, question_text, question_type, options, correct_answer, explanation, question_order)
SELECT
  quiz_target.id,
  q.question_text,
  'mcq',
  q.options::jsonb,
  q.correct_answer,
  q.explanation,
  q.q_order
FROM quiz_target, (VALUES
  ('What does `typeof null` return in JavaScript?', '[{"label":"A","text":"\"null\""},{"label":"B","text":"\"object\""},{"label":"C","text":"\"undefined\""},{"label":"D","text":"\"string\""}]', 'B', 'In JavaScript, typeof null returns "object" due to a legacy bug dating back to the first implementation of JavaScript.', 1),
  ('What is the output of `0.1 + 0.2 === 0.3` in JavaScript?', '[{"label":"A","text":"true"},{"label":"B","text":"false"},{"label":"C","text":"NaN"},{"label":"D","text":"undefined"}]', 'B', 'Due to IEEE 754 floating-point arithmetic precision limits in binary representation, 0.1 + 0.2 equals 0.30000000000000004, so the strict comparison yields false.', 2),
  ('Which keyword declares a block-scoped variable that cannot be reassigned?', '[{"label":"A","text":"var"},{"label":"B","text":"let"},{"label":"C","text":"const"},{"label":"D","text":"immutable"}]', 'C', '`const` declares a block-scoped identifier that cannot be reassigned through reassignment or re-declaration.', 3),
  ('What is a closure in JavaScript?', '[{"label":"A","text":"A function that terminates immediately after definition"},{"label":"B","text":"A function bundled together with references to its surrounding lexical environment"},{"label":"C","text":"A built-in method for terminating asynchronous callbacks"},{"label":"D","text":"A syntax error caused by unclosed parentheses"}]', 'B', 'A closure gives a function access to its outer scope even after the outer function has finished executing.', 4),
  ('Which array method tests whether all elements in the array pass the provided test function?', '[{"label":"A","text":"some()"},{"label":"B","text":"every()"},{"label":"C","text":"filter()"},{"label":"D","text":"includes()"}]', 'B', '`every()` executes a callback for each element and returns true if and only if the callback returns truthy for all elements.', 5),
  ('What does `Promise.all()` do if any of the passed promises rejects?', '[{"label":"A","text":"It waits for all other promises and ignores the rejection"},{"label":"B","text":"It immediately rejects with the reason of the first promise that rejected"},{"label":"C","text":"It resolves with null for the rejected promise"},{"label":"D","text":"It automatically retries the rejected promise up to 3 times"}]', 'B', '`Promise.all` follows an all-or-nothing fail-fast behavior: if any promise rejects, the returned promise immediately rejects.', 6),
  ('Which method appends one or more elements to the end of an array and returns its new length?', '[{"label":"A","text":"push()"},{"label":"B","text":"pop()"},{"label":"C","text":"unshift()"},{"label":"D","text":"shift()"}]', 'A', '`push()` adds elements to the end of an array, whereas `unshift()` adds elements to the beginning.', 7),
  ('What is the primary difference between `==` and `===`?', '[{"label":"A","text":"`==` compares object references while `===` compares values"},{"label":"B","text":"`===` performs type coercion before comparison while `==` does not"},{"label":"C","text":"`==` performs type coercion if types differ; `===` checks both value and type without coercion"},{"label":"D","text":"There is no difference; they are strictly interchangeable"}]', 'C', '`==` is loose equality (coercing operand types), whereas `===` is strict equality requiring identical types and values.', 8),
  ('Which keyword pauses execution inside a generator function?', '[{"label":"A","text":"await"},{"label":"B","text":"yield"},{"label":"C","text":"pause"},{"label":"D","text":"defer"}]', 'B', 'The `yield` keyword is used to pause and resume a generator function (`function*`).', 9),
  ('What does `typeof NaN` evaluate to in JavaScript?', '[{"label":"A","text":"\"NaN\""},{"label":"B","text":"\"undefined\""},{"label":"C","text":"\"number\""},{"label":"D","text":"\"object\""}]', 'C', '`NaN` stands for "Not-a-Number", but its JavaScript type is technically a numeric data type (`number`).', 10),
  ('Which method parses a JSON string, constructing the JavaScript value or object described by the string?', '[{"label":"A","text":"JSON.stringify()"},{"label":"B","text":"JSON.parse()"},{"label":"C","text":"JSON.object()"},{"label":"D","text":"JSON.decode()"}]', 'B', '`JSON.parse()` deserializes a JSON string into a JavaScript object or primitive value.', 11),
  ('What is the result of `Boolean("")`?', '[{"label":"A","text":"true"},{"label":"B","text":"false"},{"label":"C","text":"undefined"},{"label":"D","text":"null"}]', 'B', 'An empty string `""` is falsy in JavaScript, so `Boolean("")` converts to `false`.', 12),
  ('What is the Event Loop responsible for in the JavaScript runtime?', '[{"label":"A","text":"Compiling JavaScript source code into native machine assembly"},{"label":"B","text":"Monitoring the Call Stack and moving callbacks from the Task/Microtask queues onto the stack when empty"},{"label":"C","text":"Managing garbage collection memory limits exclusively"},{"label":"D","text":"Parsing CSS style sheets and computing layout geometries"}]', 'B', 'The Event Loop checks if the Call Stack is empty and pushes pending microtasks and macrotask callbacks onto it.', 13),
  ('Which array method creates a new array populated with the results of calling a provided function on every element?', '[{"label":"A","text":"forEach()"},{"label":"B","text":"map()"},{"label":"C","text":"filter()"},{"label":"D","text":"reduce()"}]', 'B', '`map()` transforms each element and returns a brand new array of equal length.', 14),
  ('What does `Object.freeze()` do to an object?', '[{"label":"A","text":"Prevents new properties from being added, but existing properties can still be modified"},{"label":"B","text":"Prevents additions, deletions, and modifications of existing properties and prototype"},{"label":"C","text":"Hides properties from enumeration in for...in loops"},{"label":"D","text":"Creates an asynchronous deep copy of the object"}]', 'B', '`Object.freeze()` makes an object completely immutable at a shallow level.', 15),
  ('Which method removes the first element from an array and returns that removed element?', '[{"label":"A","text":"shift()"},{"label":"B","text":"pop()"},{"label":"C","text":"unshift()"},{"label":"D","text":"splice()"}]', 'A', '`shift()` removes the first element (index 0) and shifts all remaining elements down one position.', 16),
  ('In strict mode (`"use strict"`), what is the value of `this` inside an un-bound, plain function invoked directly?', '[{"label":"A","text":"window / global"},{"label":"B","text":"undefined"},{"label":"C","text":"null"},{"label":"D","text":"{}"}]', 'B', 'In strict mode, the default binding of `this` in standalone functions is `undefined` rather than the global object.', 17),
  ('What does `Array.isArray([])` return?', '[{"label":"A","text":"false"},{"label":"B","text":"true"},{"label":"C","text":"\"array\""},{"label":"D","text":"undefined"}]', 'B', '`Array.isArray()` accurately identifies arrays, returning `true` for standard arrays.', 18),
  ('Which operator is known as the Nullish Coalescing Operator in JavaScript?', '[{"label":"A","text":"||"},{"label":"B","text":"&&"},{"label":"C","text":"??"},{"label":"D","text":"?:"}]', 'C', '`??` returns the right-hand operand only when the left-hand operand is `null` or `undefined` (unlike `||` which checks for any falsy value).', 19),
  ('What does "hoisting" mean in JavaScript?', '[{"label":"A","text":"Moving DOM elements higher up the render tree"},{"label":"B","text":"Variable and function declarations are conceptually moved to the top of their enclosing scope before code execution"},{"label":"C","text":"Converting asynchronous operations into synchronous executions"},{"label":"D","text":"Elevating errors to higher-level try/catch blocks automatically"}]', 'B', 'Hoisting allows functions and variables declared with `var` to be referenced before their lexical declarations.', 20),
  ('What is the behavior of `Promise.race()`?', '[{"label":"A","text":"It returns all settled promises sorted by execution time"},{"label":"B","text":"It returns a promise that fulfills or rejects as soon as any one of the input promises settles"},{"label":"C","text":"It rejects only if every single promise rejects"},{"label":"D","text":"It executes promises in sequential priority order"}]', 'B', '`Promise.race()` settles (fulfills or rejects) with the eventual state of whichever promise finishes first.', 21),
  ('Which ES6 built-in object lets you store unique values of any type, whether primitive values or object references?', '[{"label":"A","text":"Map"},{"label":"B","text":"WeakMap"},{"label":"C","text":"Set"},{"label":"D","text":"Symbol"}]', 'C', 'A `Set` is a collection of unique values; duplicate entries are automatically discarded.', 22),
  ('What is the result of evaluating `[1, 2] + [3, 4]` in JavaScript?', '[{"label":"A","text":"[1, 2, 3, 4]"},{"label":"B","text":"\"1,23,4\""},{"label":"C","text":"NaN"},{"label":"D","text":"TypeError"}]', 'B', 'The binary `+` operator converts both arrays into strings ("1,2" and "3,4") and concatenates them into `"1,23,4"`.', 23),
  ('Which method returns an array of a given object''s own enumerable property names?', '[{"label":"A","text":"Object.values()"},{"label":"B","text":"Object.keys()"},{"label":"C","text":"Object.entries()"},{"label":"D","text":"Object.getOwnPropertyNames()"}]', 'B', '`Object.keys()` returns an array containing all string-keyed enumerable property names directly defined on the object.', 24),
  ('How do you stop an event from propagating (bubbling) further up the DOM hierarchy?', '[{"label":"A","text":"event.preventDefault()"},{"label":"B","text":"event.stopPropagation()"},{"label":"C","text":"event.exit()"},{"label":"D","text":"return false"}]', 'B', '`event.stopPropagation()` stops the dispatch of the DOM event along its capture or bubbling phase.', 25),
  ('What does `typeof undefined` return?', '[{"label":"A","text":"\"null\""},{"label":"B","text":"\"undefined\""},{"label":"C","text":"\"void\""},{"label":"D","text":"\"object\""}]', 'B', '`typeof undefined` returns the literal string `"undefined"`.', 26),
  ('What does `event.preventDefault()` accomplish?', '[{"label":"A","text":"Cancels the default action belonging to the event (e.g. following a link or submitting a form)"},{"label":"B","text":"Stops child elements from triggering event handlers"},{"label":"C","text":"Destroys the active event listener from memory"},{"label":"D","text":"Prevents CSS pseudo-classes like :hover from firing"}]', 'A', '`preventDefault()` signals to the user agent that if the event is not explicitly handled, its default action should not be taken.', 27),
  ('What does `Array.prototype.reduce()` accomplish?', '[{"label":"A","text":"Reduces the size of an array by truncating trailing elements"},{"label":"B","text":"Executes a user-supplied reducer callback on each element, passing the return value from the calculation on the preceding element"},{"label":"C","text":"Filters out duplicate values from an array"},{"label":"D","text":"Sorts the array descending order"}]', 'B', '`reduce()` accumulates array values into a single consolidated output value according to the reducer function.', 28),
  ('What is a key property of `WeakMap` in JavaScript?', '[{"label":"A","text":"Keys can be primitives or objects"},{"label":"B","text":"Keys must be objects, and they do not prevent garbage collection if no other references exist"},{"label":"C","text":"Its entries can be enumerated with for...of"},{"label":"D","text":"It automatically persists its keys into localStorage"}]', 'B', '`WeakMap` keys must be objects and are held weakly, preventing memory leaks when objects are discarded elsewhere.', 29),
  ('What does `typeof (() => {})` evaluate to?', '[{"label":"A","text":"\"object\""},{"label":"B","text":"\"function\""},{"label":"C","text":"\"arrow\""},{"label":"D","text":"\"undefined\""}]', 'B', 'Functions and arrow functions are first-class objects whose `typeof` evaluation is `"function"`.', 30)
) AS q(question_text, options, correct_answer, explanation, q_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions qqs JOIN public.quizzes qz ON qqs.quiz_id = qz.id
  WHERE qz.skill_name = 'JavaScript' AND qqs.question_text = q.question_text
);

-- ─── REACT QUESTIONS (30 questions) ───
WITH quiz_target AS (SELECT id FROM public.quizzes WHERE skill_name = 'React' LIMIT 1)
INSERT INTO public.quiz_questions (quiz_id, question_text, question_type, options, correct_answer, explanation, question_order)
SELECT
  quiz_target.id,
  q.question_text,
  'mcq',
  q.options::jsonb,
  q.correct_answer,
  q.explanation,
  q.q_order
FROM quiz_target, (VALUES
  ('What is the primary purpose of the Virtual DOM in React?', '[{"label":"A","text":"To store encrypted user credentials securely"},{"label":"B","text":"To optimize DOM manipulation for performance by calculating diffs in memory"},{"label":"C","text":"To manage backend database routing and migrations"},{"label":"D","text":"To eliminate the need for CSS stylesheets"}]', 'B', 'React maintains a lightweight virtual representation of the UI in memory, calculating the minimal set of changes before updating the browser DOM.', 1),
  ('Which React hook is used to handle side effects like data fetching and subscriptions?', '[{"label":"A","text":"useState"},{"label":"B","text":"useMemo"},{"label":"C","text":"useEffect"},{"label":"D","text":"useCallback"}]', 'C', '`useEffect` runs side effects after rendering, including API calls, event listeners, and manual DOM manipulation.', 2),
  ('How do you pass data down from a parent component to a child component?', '[{"label":"A","text":"Using State"},{"label":"B","text":"Using Props"},{"label":"C","text":"Using HTML dataset attributes"},{"label":"D","text":"Using Redux stores only"}]', 'B', 'Props (short for properties) are the standard unidirectional mechanism for passing data down from parent to child components.', 3),
  ('What does JSX stand for?', '[{"label":"A","text":"Java Standard XML"},{"label":"B","text":"JavaScript XML"},{"label":"C","text":"JavaScript Syntax Extension"},{"label":"D","text":"JSON Syntax XML"}]', 'B', 'JSX stands for JavaScript XML. It is a syntax extension that lets you write HTML-like markup inside JavaScript.', 4),
  ('What is the correct way to update state that depends on the previous state?', '[{"label":"A","text":"count = count + 1"},{"label":"B","text":"setCount(count + 1)"},{"label":"C","text":"setCount(prev => prev + 1)"},{"label":"D","text":"this.state.count++"}]', 'C', 'Passing a function `setCount(prev => prev + 1)` guarantees you are calculating the new state based on the most up-to-date pending state.', 5),
  ('What is the purpose of the `key` prop when rendering dynamic lists in React?', '[{"label":"A","text":"To apply unique CSS styles to list items"},{"label":"B","text":"To help React identify which items have changed, been added, or removed for efficient reconciliation"},{"label":"C","text":"To bind items to database primary keys automatically"},{"label":"D","text":"To prevent items from receiving user click events"}]', 'B', 'Keys provide a stable identity to list items across renders, avoiding unnecessary DOM re-creations and maintaining input state.', 6),
  ('What is the purpose of the `useMemo` hook?', '[{"label":"A","text":"Memoizes a callback function definition"},{"label":"B","text":"Memoizes the result of an expensive calculation to avoid recalculating on every render"},{"label":"C","text":"Automatically manages local component state"},{"label":"D","text":"Provides global application routing"}]', 'B', '`useMemo` caches the result of a calculation between renders, only recomputing when its specified dependencies change.', 7),
  ('Which hook allows you to persist a mutable value or reference a DOM element directly without triggering a re-render?', '[{"label":"A","text":"useState"},{"label":"B","text":"useRef"},{"label":"C","text":"useEffect"},{"label":"D","text":"useImperativeHandle"}]', 'B', '`useRef` returns a mutable ref object whose `.current` property persists across renders without causing component re-renders when updated.', 8),
  ('What does the `useCallback` hook memoize?', '[{"label":"A","text":"A calculated value"},{"label":"B","text":"A function definition / reference"},{"label":"C","text":"A Redux state tree"},{"label":"D","text":"A DOM node reference"}]', 'B', '`useCallback` caches a function definition between renders so child components relying on reference equality do not re-render unnecessarily.', 9),
  ('What does `React.memo()` do?', '[{"label":"A","text":"It memoizes an entire React component, skipping re-renders if its props have not changed"},{"label":"B","text":"It saves component data into the browser''s sessionStorage"},{"label":"C","text":"It creates a memoized custom hook automatically"},{"label":"D","text":"It forces a component to re-render every second"}]', 'A', '`React.memo` is a higher-order component that performs a shallow comparison of props to avoid re-rendering pure components.', 10),
  ('Which of the following causes a React component to re-render?', '[{"label":"A","text":"Updating a useRef current value"},{"label":"B","text":"State changes or props changes"},{"label":"C","text":"Reading an ordinary local variable"},{"label":"D","text":"Adding a comment inside the JSX"}]', 'B', 'When a component''s state or props change, React schedules a re-render of that component and its children.', 11),
  ('What is a fundamental Rule of React Hooks?', '[{"label":"A","text":"Hooks must only be called inside loops or conditions"},{"label":"B","text":"Hooks must be called at the top level of React function components or custom hooks, never inside loops or conditions"},{"label":"C","text":"Hooks can only be called inside class components"},{"label":"D","text":"Hooks must always be declared as async functions"}]', 'B', 'Hooks must execute in the exact same order on every render, so they cannot be placed inside conditions, loops, or nested functions.', 12),
  ('When does `useEffect(callback, [])` (with an empty dependency array) run?', '[{"label":"A","text":"On every single render and re-render"},{"label":"B","text":"Only once after the initial component mount"},{"label":"C","text":"Before the component mounts into the DOM"},{"label":"D","text":"Only when the component throws an error"}]', 'B', 'An empty dependency array `[]` indicates the effect does not depend on any state or props, running only once after initial mount.', 13),
  ('Which built-in API avoids "prop drilling" by sharing data across the component tree without passing props manually at every level?', '[{"label":"A","text":"Context API"},{"label":"B","text":"Web Workers"},{"label":"C","text":"localStorage"},{"label":"D","text":"Service Workers"}]', 'A', 'The Context API (`createContext` and `useContext`) provides a way to pass data through the component tree without prop drilling.', 14),
  ('What is a "controlled component" in React form handling?', '[{"label":"A","text":"A component whose rendered HTML is controlled directly by third-party jQuery scripts"},{"label":"B","text":"An input form element whose current value is driven by React component state"},{"label":"C","text":"A component that cannot receive user input events"},{"label":"D","text":"A component rendered exclusively on the server"}]', 'B', 'In a controlled component, form input values are bound to React state and updated via event handlers (`onChange`).', 15),
  ('What hook is recommended for managing complex local state transitions with action types?', '[{"label":"A","text":"useReducer"},{"label":"B","text":"useState"},{"label":"C","text":"useTransition"},{"label":"D","text":"useLayoutEffect"}]', 'A', '`useReducer` is preferable to `useState` when state logic is complex or when the next state depends on multiple previous sub-values.', 16),
  ('Why should state never be mutated directly (e.g. `state.user = "Alice"`) in React?', '[{"label":"A","text":"Direct mutations cause immediate syntax compilation errors"},{"label":"B","text":"React relies on state immutability to detect state changes and schedule re-renders"},{"label":"C","text":"Direct mutations corrupt the browser''s DOM tree permanently"},{"label":"D","text":"React state is stored in read-only cookies"}]', 'B', 'React compares state references; modifying properties in-place prevents React from recognizing changes and updating the UI.', 17),
  ('What is React Fragment (`<React.Fragment>` or `<></>`) used for?', '[{"label":"A","text":"Creating an isolated web worker thread"},{"label":"B","text":"Grouping a list of child elements without adding extra wrapper nodes to the browser DOM"},{"label":"C","text":"Styling elements with flexbox automatically"},{"label":"D","text":"Handling uncaught JavaScript runtime exceptions"}]', 'B', 'Fragments let you return multiple sibling elements without rendering unnecessary `<div>` or wrapper elements into the DOM.', 18),
  ('What does the cleanup function returned inside `useEffect` do?', '[{"label":"A","text":"Deletes the component''s source code from memory"},{"label":"B","text":"Cleans up subscriptions, timers, or event listeners before the component unmounts or before re-running the effect"},{"label":"C","text":"Resets all component state variables to null"},{"label":"D","text":"Empties the browser cache and cookies"}]', 'B', 'The cleanup function executes before the component unmounts or prior to re-executing the effect with updated dependencies.', 19),
  ('How can a parent component obtain a ref to an inner DOM element rendered by a custom child component?', '[{"label":"A","text":"React.forwardRef"},{"label":"B","text":"React.createRef"},{"label":"C","text":"React.cloneElement"},{"label":"D","text":"React.memo"}]', 'A', '`React.forwardRef` creates a React component that forwards the `ref` attribute it receives to a child node further down the tree.', 20),
  ('What is an Error Boundary in React?', '[{"label":"A","text":"A hook that logs warnings in the browser console"},{"label":"B","text":"A component that catches JavaScript errors anywhere in its child component tree and displays a fallback UI"},{"label":"C","text":"A linter rule checking for syntax flaws in JSX"},{"label":"D","text":"A network timeout interceptor for Axios requests"}]', 'B', 'Error Boundaries catch JavaScript errors in their child tree during rendering, in lifecycle methods, and in constructors.', 21),
  ('In React 18, which hook allows you to mark specific state updates as non-blocking transitions?', '[{"label":"A","text":"useTransition"},{"label":"B","text":"useDeferredValue"},{"label":"C","text":"useId"},{"label":"D","text":"useSyncExternalStore"}]', 'A', '`useTransition` allows you to mark state updates as non-urgent transitions, keeping the user interface responsive during intensive updates.', 22),
  ('What does `useLayoutEffect` do differently from `useEffect`?', '[{"label":"A","text":"It runs on a separate web worker thread"},{"label":"B","text":"It fires synchronously after all DOM mutations but before the browser paints on screen"},{"label":"C","text":"It only runs when the window is resized"},{"label":"D","text":"It cannot read layout dimensions from the DOM"}]', 'B', '`useLayoutEffect` executes synchronously immediately after React updates the DOM, allowing layout measurements without visual flicker.', 23),
  ('What is the purpose of the `children` prop in React?', '[{"label":"A","text":"It contains the number of child components rendered"},{"label":"B","text":"It allows components to be composed by passing arbitrary nested elements into their body"},{"label":"C","text":"It links child elements directly to parent database rows"},{"label":"D","text":"It specifies the CSS grid column span of child elements"}]', 'B', '`props.children` allows components to receive and render nested JSX passed between their opening and closing tags.', 24),
  ('What does the `useId` hook introduced in React 18 provide?', '[{"label":"A","text":"Generates unique, stable IDs across server and client for accessible form inputs and ARIA attributes"},{"label":"B","text":"Retrieves the currently authenticated user''s database ID"},{"label":"C","text":"Generates UUID v4 tokens for cryptographic signatures"},{"label":"D","text":"Returns the internal fiber node ID"}]', 'A', '`useId` produces unique IDs that match seamlessly across client and server hydration, ideal for accessibility attributes.', 25),
  ('What happens during React''s Reconciliation process?', '[{"label":"A","text":"Compiling JSX into WebAssembly bytecode"},{"label":"B","text":"Comparing the new Virtual DOM tree with the previous one to compute the minimal set of real DOM operations"},{"label":"C","text":"Validating user passwords against an encrypted database"},{"label":"D","text":"Minifying JavaScript asset bundles for deployment"}]', 'B', 'Reconciliation is React''s diffing algorithm that computes the differences between Virtual DOM trees to update the real DOM efficiently.', 26),
  ('Can custom hooks in React call other hooks?', '[{"label":"A","text":"No, custom hooks can only call plain JavaScript functions"},{"label":"B","text":"Yes, custom hooks can call any built-in or other custom React hooks"},{"label":"C","text":"Only if they are wrapped in React.memo"},{"label":"D","text":"Only in production mode"}]', 'B', 'Custom hooks are functions starting with "use" that can compose any other hooks (`useState`, `useEffect`, etc.).', 27),
  ('What does React Portal (`ReactDOM.createPortal`) allow you to do?', '[{"label":"A","text":"Render children into a DOM node that exists outside the DOM hierarchy of the parent component"},{"label":"B","text":"Create a WebSocket tunnel between client and server"},{"label":"C","text":"Open new browser tabs without popup blockers"},{"label":"D","text":"Stream server-side rendered HTML asynchronously"}]', 'A', 'Portals render child components into a different DOM subtree (such as modals or tooltips attached to `document.body`).', 28),
  ('Why does React 18 render components twice in StrictMode during development?', '[{"label":"A","text":"To test if the monitor refresh rate is 120Hz"},{"label":"B","text":"To help detect unintended side effects and verify cleanup functions in effects"},{"label":"C","text":"It is a known regression bug in React 18"},{"label":"D","text":"To verify that CSS animations operate smoothly"}]', 'B', 'In development StrictMode, React deliberately double-invokes render methods and effects to catch impure code and missing cleanups.', 29),
  ('What is "hydration" in modern server-rendered React applications?', '[{"label":"A","text":"Downloading images into browser memory caches"},{"label":"B","text":"Attaching React event listeners and state to server-rendered HTML markup in the browser"},{"label":"C","text":"Validating form inputs before sending network requests"},{"label":"D","text":"Compiling CSS variables into static style sheets"}]', 'B', 'Hydration enables interactivity by attaching event listeners and React fiber structures to pre-rendered HTML sent from the server.', 30)
) AS q(question_text, options, correct_answer, explanation, q_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions qqs JOIN public.quizzes qz ON qqs.quiz_id = qz.id
  WHERE qz.skill_name = 'React' AND qqs.question_text = q.question_text
);

-- ─── PYTHON QUESTIONS (30 questions) ───
WITH quiz_target AS (SELECT id FROM public.quizzes WHERE skill_name = 'Python' LIMIT 1)
INSERT INTO public.quiz_questions (quiz_id, question_text, question_type, options, correct_answer, explanation, question_order)
SELECT
  quiz_target.id,
  q.question_text,
  'mcq',
  q.options::jsonb,
  q.correct_answer,
  q.explanation,
  q.q_order
FROM quiz_target, (VALUES
  ('Which keyword is used to define a function in Python?', '[{"label":"A","text":"func"},{"label":"B","text":"def"},{"label":"C","text":"function"},{"label":"D","text":"define"}]', 'B', 'In Python, functions are defined using the `def` keyword followed by the function name and parameter list.', 1),
  ('What data type is created by square brackets like `[1, 2, 3]`?', '[{"label":"A","text":"Tuple"},{"label":"B","text":"List"},{"label":"C","text":"Set"},{"label":"D","text":"Dictionary"}]', 'B', 'Square brackets define a `list`, which is an ordered, mutable sequence of elements.', 2),
  ('How do you write a single-line comment in Python?', '[{"label":"A","text":"// Comment"},{"label":"B","text":"/* Comment */"},{"label":"C","text":"# Comment"},{"label":"D","text":"<!-- Comment -->"}]', 'C', 'In Python, single-line comments start with the hash symbol `#`.', 3),
  ('Which method adds a single item to the end of a list?', '[{"label":"A","text":"add()"},{"label":"B","text":"push()"},{"label":"C","text":"append()"},{"label":"D","text":"insert()"}]', 'C', '`append()` places an element at the end of an existing list.', 4),
  ('What built-in data type stores data as key-value pairs in Python?', '[{"label":"A","text":"List"},{"label":"B","text":"Tuple"},{"label":"C","text":"Dictionary (`dict`)"},{"label":"D","text":"Set"}]', 'C', 'A dictionary (`dict`) is a collection of key-value pairs where keys must be hashable and unique.', 5),
  ('How are exceptions handled in Python?', '[{"label":"A","text":"try...catch"},{"label":"B","text":"try...except"},{"label":"C","text":"do...catch"},{"label":"D","text":"catch...finally"}]', 'B', 'Python uses `try` and `except` blocks (along with optional `else` and `finally`) to handle exceptions.', 6),
  ('What does the `__init__` method do in a Python class?', '[{"label":"A","text":"Destroys the instance when garbage collected"},{"label":"B","text":"Acts as the constructor to initialize new object instances and attributes"},{"label":"C","text":"Registers the class with the Python package manager"},{"label":"D","text":"Compiles bytecode for the module"}]', 'B', '`__init__` is the initializer method automatically invoked when a new instance of a class is created.', 7),
  ('Which statement terminates the current loop immediately?', '[{"label":"A","text":"continue"},{"label":"B","text":"break"},{"label":"C","text":"pass"},{"label":"D","text":"return"}]', 'B', '`break` terminates the smallest enclosing `for` or `while` loop prematurely.', 8),
  ('What is PEP 8 in the Python ecosystem?', '[{"label":"A","text":"A package distribution tool"},{"label":"B","text":"The official Style Guide for Python Code"},{"label":"C","text":"Python''s built-in unit testing framework"},{"label":"D","text":"The Python compiler executable"}]', 'B', 'PEP 8 provides coding conventions and styling guidelines for writing clean, readable Python code.', 9),
  ('What is the output of `type(lambda x: x)`?', '[{"label":"A","text":"<class ''lambda''>"},{"label":"B","text":"<class ''function''>"},{"label":"C","text":"<class ''object''>"},{"label":"D","text":"<class ''closure''>"}]', 'B', 'Anonymous lambda expressions create instances of the standard `<class ''function''>`.', 10),
  ('What is the primary difference between a list and a tuple in Python?', '[{"label":"A","text":"Lists are immutable; tuples are mutable"},{"label":"B","text":"Lists are mutable; tuples are immutable"},{"label":"C","text":"Tuples can only contain numbers; lists can contain any type"},{"label":"D","text":"There is no difference"}]', 'B', 'Lists can be modified (elements added, removed, or changed); tuples cannot be altered after creation.', 11),
  ('What does the `//` operator do in Python?', '[{"label":"A","text":"Exponentiation"},{"label":"B","text":"Floor division (integer division)"},{"label":"C","text":"Modulus remainder"},{"label":"D","text":"Single-line comment inside expressions"}]', 'B', '`//` divides two numbers and truncates the fractional part, returning the mathematical floor.', 12),
  ('Which keyword turns a regular function into a generator?', '[{"label":"A","text":"generate"},{"label":"B","text":"yield"},{"label":"C","text":"produce"},{"label":"D","text":"async"}]', 'B', 'Using `yield` inside a function body turns it into a generator function that produces values lazily on demand.', 13),
  ('What does the `is` operator compare in Python?', '[{"label":"A","text":"Values for equality (`==`)"},{"label":"B","text":"Memory addresses / object identity"},{"label":"C","text":"Data types only"},{"label":"D","text":"String lengths"}]', 'B', '`is` checks if two variables refer to the exact same object in memory, whereas `==` checks value equality.', 14),
  ('In a function signature, what does `*args` allow you to receive?', '[{"label":"A","text":"Keyword arguments as a dictionary"},{"label":"B","text":"An arbitrary number of positional arguments as a tuple"},{"label":"C","text":"Required arguments only"},{"label":"D","text":"Type annotations"}]', 'B', '`*args` gathers excess positional arguments into a single tuple.', 15),
  ('In a function signature, what does `**kwargs` allow you to receive?', '[{"label":"A","text":"Positional arguments as a list"},{"label":"B","text":"Arbitrary keyword arguments as a dictionary"},{"label":"C","text":"A generator expression"},{"label":"D","text":"Global module variables"}]', 'B', '`**kwargs` collects excess named keyword arguments into a standard dictionary.', 16),
  ('What is the value of `[x**2 for x in range(4)]`?', '[{"label":"A","text":"[1, 4, 9, 16]"},{"label":"B","text":"[0, 1, 4, 9]"},{"label":"C","text":"[0, 1, 2, 3]"},{"label":"D","text":"[0, 2, 4, 6]"}]', 'B', '`range(4)` yields 0, 1, 2, 3. Squaring each produces `[0, 1, 4, 9]`.', 17),
  ('Which standard library module is used for regular expressions in Python?', '[{"label":"A","text":"regex"},{"label":"B","text":"re"},{"label":"C","text":"regexp"},{"label":"D","text":"match"}]', 'B', 'The standard module for pattern matching with regular expressions is `re`.', 18),
  ('What is the Global Interpreter Lock (GIL) in CPython?', '[{"label":"A","text":"A security lock preventing unauthorized script execution"},{"label":"B","text":"A mutex that protects access to Python objects, preventing multiple native threads from executing Python bytecodes simultaneously"},{"label":"C","text":"A cryptographic hash algorithm in the hashlib module"},{"label":"D","text":"A file-system lock on open .py files"}]', 'B', 'The GIL allows only one thread to hold the Python interpreter lock in CPython, affecting CPU-bound multithreaded performance.', 19),
  ('What is the recommended idiom for safely opening and closing files in Python?', '[{"label":"A","text":"Using the `with` statement (context manager)"},{"label":"B","text":"Calling file.close() inside a loop"},{"label":"C","text":"Calling os.close_all() at script exit"},{"label":"D","text":"Using try without finally"}]', 'A', '`with open(...) as f:` ensures the file descriptor is closed automatically when leaving the block, even if exceptions occur.', 20),
  ('What does `my_dict.get("missing_key", "default")` return if "missing_key" is not present?', '[{"label":"A","text":"KeyError exception"},{"label":"B","text":"\"default\""},{"label":"C","text":"None"},{"label":"D","text":"False"}]', 'B', '`get()` returns the specified fallback default if the key is not found, avoiding a `KeyError`.', 21),
  ('What is the boolean evaluation of an empty list `bool([])` in Python?', '[{"label":"A","text":"True"},{"label":"B","text":"False"},{"label":"C","text":"None"},{"label":"D","text":"Error"}]', 'B', 'In Python, empty collections (lists, dicts, tuples, sets, strings) evaluate to `False` in boolean contexts.', 22),
  ('What does the `pass` statement do in Python?', '[{"label":"A","text":"Passes a value to the calling function"},{"label":"B","text":"Acts as a syntactic placeholder / null operation where code is syntactically required"},{"label":"C","text":"Skips the next line of code"},{"label":"D","text":"Forces the interpreter to move to the next iteration of a loop"}]', 'B', '`pass` is a null statement used as a placeholder in empty functions, loops, or classes.', 23),
  ('What does the `enumerate()` function return when iterating over a sequence?', '[{"label":"A","text":"Only the elements in reverse order"},{"label":"B","text":"Tuples containing the zero-based count/index and the value from iterating over the sequence"},{"label":"C","text":"A dictionary with indices as keys"},{"label":"D","text":"The length of the sequence"}]', 'B', '`enumerate()` yields pairs of `(index, item)` during iteration.', 24),
  ('Which built-in function aggregates elements from two or more iterables into tuples?', '[{"label":"A","text":"combine()"},{"label":"B","text":"zip()"},{"label":"C","text":"merge()"},{"label":"D","text":"chain()"}]', 'B', '`zip(*iterables)` pairs elements from each iterable until the shortest iterable is exhausted.', 25),
  ('What is a decorator in Python?', '[{"label":"A","text":"A CSS class applied to Tkinter UI elements"},{"label":"B","text":"A callable that takes another function as an argument and extends its behavior without modifying it"},{"label":"C","text":"A method that formats strings into HTML tables"},{"label":"D","text":"A keyword used for declaring global constants"}]', 'B', 'A decorator (denoted by `@decorator_name`) wraps a function or class to augment its behavior.', 26),
  ('What does `dir(obj)` return?', '[{"label":"A","text":"The file path of the script directory"},{"label":"B","text":"A list of the attributes and methods of the specified object"},{"label":"C","text":"The memory address of the object"},{"label":"D","text":"A dictionary of all global variables"}]', 'B', '`dir()` returns a sorted list of valid attribute and method names for the object.', 27),
  ('What does `sorted([3, 1, 2])` return versus `[3, 1, 2].sort()`?', '[{"label":"A","text":"`sorted()` returns a new sorted list; `.sort()` sorts the list in place and returns `None`"},{"label":"B","text":"`sorted()` sorts in place; `.sort()` returns a new list"},{"label":"C","text":"Both return brand new lists"},{"label":"D","text":"Both sort in place"}]', 'A', '`sorted()` produces a new sorted list, while list method `.sort()` mutates the original list in place and returns `None`.', 28),
  ('How do you create a set with numbers 1, 2, and 3?', '[{"label":"A","text":"{1, 2, 3}"},{"label":"B","text":"[1, 2, 3]"},{"label":"C","text":"(1, 2, 3)"},{"label":"D","text":"set: [1, 2, 3]"}]', 'A', 'Curly braces `{1, 2, 3}` without key:value pairs create a `set`.', 29),
  ('What does `str.split(",")` do on `"apple,banana,orange"`?', '[{"label":"A","text":"[\"apple\", \"banana\", \"orange\"]"},{"label":"B","text":"(\"apple\", \"banana\", \"orange\")"},{"label":"C","text":"{\"apple\", \"banana\", \"orange\"}"},{"label":"D","text":"\"apple banana orange\""}]', 'A', '`split()` breaks a string by the specified delimiter into a list of substrings.', 30)
) AS q(question_text, options, correct_answer, explanation, q_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions qqs JOIN public.quizzes qz ON qqs.quiz_id = qz.id
  WHERE qz.skill_name = 'Python' AND qqs.question_text = q.question_text
);

-- ─── SQL QUESTIONS (30 questions) ───
WITH quiz_target AS (SELECT id FROM public.quizzes WHERE skill_name = 'SQL' LIMIT 1)
INSERT INTO public.quiz_questions (quiz_id, question_text, question_type, options, correct_answer, explanation, question_order)
SELECT
  quiz_target.id,
  q.question_text,
  'mcq',
  q.options::jsonb,
  q.correct_answer,
  q.explanation,
  q.q_order
FROM quiz_target, (VALUES
  ('Which SQL statement is used to retrieve data from a database?', '[{"label":"A","text":"GET"},{"label":"B","text":"SELECT"},{"label":"C","text":"FETCH"},{"label":"D","text":"PULL"}]', 'B', '`SELECT` is the primary SQL command used to query and extract rows from database tables.', 1),
  ('Which clause is used to combine rows from two or more tables based on a related column?', '[{"label":"A","text":"COMBINE"},{"label":"B","text":"JOIN"},{"label":"C","text":"MERGE"},{"label":"D","text":"UNION"}]', 'B', '`JOIN` operations (INNER, LEFT, RIGHT, FULL) combine columns from multiple tables using shared keys.', 2),
  ('What is a PRIMARY KEY constraint in relational databases?', '[{"label":"A","text":"A column that permits duplicates but not nulls"},{"label":"B","text":"A column (or set of columns) that uniquely identifies each row in a table"},{"label":"C","text":"An encryption key used for column-level security"},{"label":"D","text":"A pointer to an external file on disk"}]', 'B', 'A primary key uniquely identifies each record in a table; it cannot contain NULLs and must be strictly unique.', 3),
  ('Which SQL clause is used to filter records AFTER an aggregation (`GROUP BY`) has been performed?', '[{"label":"A","text":"WHERE"},{"label":"B","text":"HAVING"},{"label":"C","text":"FILTER"},{"label":"D","text":"ORDER BY"}]', 'B', '`WHERE` filters rows before aggregation; `HAVING` filters aggregated groups created by `GROUP BY`.', 4),
  ('What does `COUNT(*)` return in SQL?', '[{"label":"A","text":"The count of non-null values in the first column"},{"label":"B","text":"The total number of rows matching the query criteria, including rows with NULL values"},{"label":"C","text":"The sum of all integer columns"},{"label":"D","text":"The number of tables in the database"}]', 'B', '`COUNT(*)` counts all matching rows in the table or group, regardless of NULL values.', 5),
  ('What is a FOREIGN KEY in relational database design?', '[{"label":"A","text":"A key stored in a different country for compliance"},{"label":"B","text":"A column that references the primary key of another table, enforcing referential integrity"},{"label":"C","text":"A temporary index discarded after query completion"},{"label":"D","text":"A key generated by third-party APIs"}]', 'B', 'Foreign keys establish relationships between tables by pointing to the candidate/primary key of another table.', 6),
  ('Which keyword eliminates duplicate rows from query results?', '[{"label":"A","text":"UNIQUE"},{"label":"B","text":"DISTINCT"},{"label":"C","text":"DIFFERENT"},{"label":"D","text":"DEDUPE"}]', 'B', '`SELECT DISTINCT` returns only unique rows from the specified result set.', 7),
  ('What is the primary purpose of creating an INDEX on database columns?', '[{"label":"A","text":"To compress database files on disk"},{"label":"B","text":"To speed up data retrieval operations at the cost of additional storage and slower writes"},{"label":"C","text":"To prevent unauthorized users from viewing table data"},{"label":"D","text":"To automatically backup tables periodically"}]', 'B', 'Indexes (like B-trees) accelerate `SELECT` lookups and `WHERE` filters, but increase storage and write overhead on inserts/updates.', 8),
  ('What does `NULL` represent in relational SQL databases?', '[{"label":"A","text":"Zero (`0`)"},{"label":"B","text":"An empty string (`\"\"`)"},{"label":"C","text":"Missing, unknown, or inapplicable data"},{"label":"D","text":"Boolean False"}]', 'C', '`NULL` signifies the absence of a value; it is neither equal to zero nor empty string, and `NULL = NULL` evaluates to unknown.', 9),
  ('Which SQL command quickly removes ALL rows from a table without logging individual row deletions?', '[{"label":"A","text":"DELETE ALL"},{"label":"B","text":"TRUNCATE"},{"label":"C","text":"DROP"},{"label":"D","text":"CLEAR"}]', 'B', '`TRUNCATE TABLE` empties a table quickly by deallocating data pages rather than deleting rows one by one.', 10),
  ('What rows does an `INNER JOIN` return?', '[{"label":"A","text":"All rows from the left table and matching rows from the right table"},{"label":"B","text":"Only rows where there is a match in both tables"},{"label":"C","text":"All rows from both tables, pairing unmatched rows with NULL"},{"label":"D","text":"Rows from the left table that have NO match in the right table"}]', 'B', '`INNER JOIN` selects records that have matching values in both joined tables.', 11),
  ('What rows does a `LEFT JOIN` (LEFT OUTER JOIN) return?', '[{"label":"A","text":"Only rows that match in both tables"},{"label":"B","text":"All rows from the left table, and matched rows from the right table (with NULLs for unmatched right rows)"},{"label":"C","text":"All rows from the right table and only matching rows from the left"},{"label":"D","text":"Only rows that have no match in the right table"}]', 'B', '`LEFT JOIN` returns all records from the left table regardless of whether a matching record exists in the right table.', 12),
  ('What does the "A" in the database acronym ACID stand for?', '[{"label":"A","text":"Availability"},{"label":"B","text":"Atomicity"},{"label":"C","text":"Asynchronous"},{"label":"D","text":"Authorization"}]', 'B', 'Atomicity guarantees that all operations within a transaction succeed completely or are entirely rolled back (all-or-nothing).', 13),
  ('What does the "I" in ACID stand for?', '[{"label":"A","text":"Indexing"},{"label":"B","text":"Isolation"},{"label":"C","text":"Integrity"},{"label":"D","text":"Idempotency"}]', 'B', 'Isolation ensures that concurrent transactions do not interfere with each other''s intermediate states.', 14),
  ('Which database normal form eliminates transitive dependencies (non-key attributes depending on other non-key attributes)?', '[{"label":"A","text":"First Normal Form (1NF)"},{"label":"B","text":"Second Normal Form (2NF)"},{"label":"C","text":"Third Normal Form (3NF)"},{"label":"D","text":"BCNF"}]', 'C', 'Third Normal Form (3NF) requires 2NF and that no non-prime attribute is transitively dependent on the primary key.', 15),
  ('Which SQL statement undoes the modifications made in the current uncommitted transaction?', '[{"label":"A","text":"REVERT"},{"label":"B","text":"ROLLBACK"},{"label":"C","text":"UNDO"},{"label":"D","text":"CANCEL"}]', 'B', '`ROLLBACK` restores the database state to the beginning of the transaction or a designated savepoint.', 16),
  ('What is the difference between `UNION` and `UNION ALL`?', '[{"label":"A","text":"`UNION` removes duplicate rows from the combined result set; `UNION ALL` retains all duplicates"},{"label":"B","text":"`UNION ALL` removes duplicates; `UNION` does not"},{"label":"C","text":"`UNION` operates on tables; `UNION ALL` operates on views only"},{"label":"D","text":"There is no difference"}]', 'A', '`UNION` performs a deduplication step (equivalent to DISTINCT), while `UNION ALL` concatenates datasets without removing duplicates.', 17),
  ('What is a Composite Primary Key?', '[{"label":"A","text":"A primary key composed of two or more columns combined together"},{"label":"B","text":"A primary key that automatically compresses data"},{"label":"C","text":"A primary key linked to a foreign table"},{"label":"D","text":"A key generated by hashing multiple tables"}]', 'A', 'A composite primary key uses two or more columns together to uniquely identify a record.', 18),
  ('What does the `DROP TABLE` command do?', '[{"label":"A","text":"Empties rows while keeping table structure and schema intact"},{"label":"B","text":"Permanently deletes the table schema, definition, indexes, and all its data"},{"label":"C","text":"Hides the table from public SELECT queries"},{"label":"D","text":"Archives table records into CSV format"}]', 'B', '`DROP TABLE` deletes the entire table structure, triggers, constraints, and data from the database schema.', 19),
  ('Which function returns the first non-null value among its arguments?', '[{"label":"A","text":"NULLIF()"},{"label":"B","text":"COALESCE()"},{"label":"C","text":"IFNULL()"},{"label":"D","text":"ISNULL()"}]', 'B', '`COALESCE(val1, val2, ...)` evaluates arguments in order and returns the current value of the first expression that does not evaluate to NULL.', 20),
  ('What is a Database View?', '[{"label":"A","text":"A physical copy of table data stored in RAM"},{"label":"B","text":"A saved, named virtual table defined by a query that executes dynamically when queried"},{"label":"C","text":"A GUI tool used by database administrators"},{"label":"D","text":"A hardware monitor for disk usage"}]', 'B', 'A view is a stored query that presents data from underlying tables as if it were a regular table.', 21),
  ('What is the defining characteristic of a Clustered Index?', '[{"label":"A","text":"It stores pointers to rows stored elsewhere on disk"},{"label":"B","text":"It dictates the physical sorting and storage order of the actual table rows on disk"},{"label":"C","text":"A table can have up to 255 clustered indexes"},{"label":"D","text":"It is only used for caching full-text search strings"}]', 'B', 'A clustered index sorts and stores the data rows in the table based on their key values (each table can have only one clustered index).', 22),
  ('What does the pattern `LIKE "%test"` match in SQL?', '[{"label":"A","text":"Strings that start with \"test\""},{"label":"B","text":"Strings that end with \"test\""},{"label":"C","text":"Strings that contain \"test\" anywhere"},{"label":"D","text":"Exact string \"test\" only"}]', 'B', 'The `%` wildcard matches zero or more characters, so `"%test"` matches any string ending with "test".', 23),
  ('What is the default sort order of the `ORDER BY` clause?', '[{"label":"A","text":"DESC (Descending)"},{"label":"B","text":"ASC (Ascending)"},{"label":"C","text":"Random"},{"label":"D","text":"Insertion order"}]', 'B', 'If unspecified, `ORDER BY` sorts values in ascending (`ASC`) order (from lowest to highest).', 24),
  ('What does `ON DELETE CASCADE` specify on a Foreign Key constraint?', '[{"label":"A","text":"Prevents deletion of the referenced parent row"},{"label":"B","text":"Automatically deletes matching child rows when the referenced parent row is deleted"},{"label":"C","text":"Sets foreign key values in child rows to NULL upon parent deletion"},{"label":"D","text":"Sends an error notification to connected clients"}]', 'B', '`ON DELETE CASCADE` automatically propagates deletions from parent tables down to related child records.', 25),
  ('What do SQL Window Functions (like `ROW_NUMBER() OVER (...)`) do?', '[{"label":"A","text":"Open modal popup windows in web browsers"},{"label":"B","text":"Perform calculations across a set of table rows related to the current row without collapsing the rows into a single output group"},{"label":"C","text":"Encrypt table data during transmission over SSL"},{"label":"D","text":"Limit the number of database connections per client"}]', 'B', 'Window functions perform calculations across partitions of rows while retaining individual row identities.', 26),
  ('Which SQL command is used to add or modify columns in an existing table?', '[{"label":"A","text":"UPDATE TABLE"},{"label":"B","text":"ALTER TABLE"},{"label":"C","text":"MODIFY TABLE"},{"label":"D","text":"CHANGE TABLE"}]', 'B', '`ALTER TABLE` is used to add, modify, or drop columns and constraints on existing tables.', 27),
  ('What is SQL Injection?', '[{"label":"A","text":"A performance optimization technique for bulk inserting data"},{"label":"B","text":"A security vulnerability where malicious SQL commands are injected into input fields and executed by the database"},{"label":"C","text":"Automated database schema migration scripts"},{"label":"D","text":"Replication of database logs across regions"}]', 'B', 'SQL Injection occurs when untrusted user inputs are concatenated directly into SQL queries rather than using parameterized queries.', 28),
  ('What is the purpose of a Database Transaction Savepoint?', '[{"label":"A","text":"To export a database dump to an Amazon S3 bucket"},{"label":"B","text":"To establish a checkpoint within a transaction to which you can later roll back without discarding the entire transaction"},{"label":"C","text":"To lock the database against read queries"},{"label":"D","text":"To save user login sessions"}]', 'B', 'Savepoints (`SAVEPOINT name`) allow partial rollbacks (`ROLLBACK TO name`) within a larger active transaction.', 29),
  ('What does a Cross Join (Cartesian Product) produce?', '[{"label":"A","text":"Only matching rows between two tables"},{"label":"B","text":"Every row from the first table combined with every row from the second table (M × N rows)"},{"label":"C","text":"An empty result set"},{"label":"D","text":"A union of the two tables'' column names"}]', 'B', 'A `CROSS JOIN` produces the Cartesian product of two tables, returning every possible combination of rows.', 30)
) AS q(question_text, options, correct_answer, explanation, q_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions qqs JOIN public.quizzes qz ON qqs.quiz_id = qz.id
  WHERE qz.skill_name = 'SQL' AND qqs.question_text = q.question_text
);

-- ─── SYSTEM DESIGN QUESTIONS (30 questions) ───
WITH quiz_target AS (SELECT id FROM public.quizzes WHERE skill_name = 'System Design' LIMIT 1)
INSERT INTO public.quiz_questions (quiz_id, question_text, question_type, options, correct_answer, explanation, question_order)
SELECT
  quiz_target.id,
  q.question_text,
  'mcq',
  q.options::jsonb,
  q.correct_answer,
  q.explanation,
  q.q_order
FROM quiz_target, (VALUES
  ('What is Horizontal Scaling (Scaling Out)?', '[{"label":"A","text":"Adding more RAM, CPU, or storage to an existing single machine"},{"label":"B","text":"Adding more machines or servers to a pool of distributed resources"},{"label":"C","text":"Increasing screen resolution for user dashboards"},{"label":"D","text":"Compressing database indices"}]', 'B', 'Horizontal scaling means adding more node instances to share workload, whereas vertical scaling means adding power to a single node.', 1),
  ('In the CAP Theorem, what does "Consistency" (C) guarantee?', '[{"label":"A","text":"All client requests will succeed with 200 OK"},{"label":"B","text":"Every read receives the most recent write or an error"},{"label":"C","text":"The database schema remains immutable"},{"label":"D","text":"Transactions execute without locks"}]', 'B', 'Consistency in CAP means all nodes see the same data at the same time, returning the latest write or an error.', 2),
  ('In the CAP Theorem, what does "Availability" (A) guarantee?', '[{"label":"A","text":"Every non-failing node returns a non-error response for every request, without guarantee of containing the latest write"},{"label":"B","text":"Zero network latency for international users"},{"label":"C","text":"Servers never crash or reboot"},{"label":"D","text":"Data is replicated across 10 continents"}]', 'A', 'Availability ensures that every non-failing node returns a reasonable response to every received request.', 3),
  ('In the CAP Theorem, what does "Partition Tolerance" (P) mean?', '[{"label":"A","text":"The database partitions tables into horizontal shards"},{"label":"B","text":"The system continues to operate despite an arbitrary number of dropped or delayed messages between nodes (network partition)"},{"label":"C","text":"Users can partition their accounts into teams"},{"label":"D","text":"Disk drives can be partitioned into FAT32 or NTFS"}]', 'B', 'Partition tolerance means the distributed system functions properly even when network communication between nodes breaks down.', 4),
  ('What is the primary function of a Load Balancer?', '[{"label":"A","text":"To distribute incoming network traffic across multiple backend servers to prevent overload and maximize throughput"},{"label":"B","text":"To convert SQL queries into NoSQL documents"},{"label":"C","text":"To monitor disk hardware temperatures"},{"label":"D","text":"To encrypt user hard drives"}]', 'A', 'Load balancers sit between clients and backend servers, evenly distributing incoming requests based on algorithms like round-robin or least-connections.', 5),
  ('Which caching strategy writes data to both the cache and the primary database simultaneously before returning success?', '[{"label":"A","text":"Write-Around"},{"label":"B","text":"Write-Back (Write-Behind)"},{"label":"C","text":"Write-Through"},{"label":"D","text":"Cache-Aside"}]', 'C', 'In Write-Through caching, writes are written to the cache and the permanent database synchronously, ensuring strong data consistency.', 6),
  ('What is Database Sharding?', '[{"label":"A","text":"Creating read-only mirrors of the entire database"},{"label":"B","text":"Horizontally partitioning data so that subsets of rows reside across distinct database server instances"},{"label":"C","text":"Backing up database tables to cold magnetic tape"},{"label":"D","text":"Converting relational tables into graph models"}]', 'B', 'Sharding splits a large dataset horizontally across multiple database servers based on a shard key.', 7),
  ('What is a CDN (Content Delivery Network) primarily used for?', '[{"label":"A","text":"Deploying machine learning models to mobile devices"},{"label":"B","text":"Serving cached static assets (images, videos, JS/CSS) from edge servers physically close to users to reduce latency"},{"label":"C","text":"Running complex database stored procedures"},{"label":"D","text":"Managing employee email accounts"}]', 'B', 'A CDN is a distributed network of edge servers that delivers web content geographically close to users, cutting down round-trip latency.', 8),
  ('Why are Message Queues (like RabbitMQ or Apache Kafka) introduced into system architectures?', '[{"label":"A","text":"To replace SQL databases for transaction processing"},{"label":"B","text":"To decouple systems and enable asynchronous, non-blocking communication and buffer traffic spikes"},{"label":"C","text":"To serve frontend HTML pages directly to users"},{"label":"D","text":"To eliminate the need for load balancers"}]', 'B', 'Message queues decouple producer and consumer services, enabling asynchronous processing and smoothing out traffic spikes.', 9),
  ('What is a Reverse Proxy?', '[{"label":"A","text":"A proxy that allows internal employees to browse external websites anonymously"},{"label":"B","text":"A server that sits in front of backend web servers, intercepting requests to provide caching, SSL termination, and security"},{"label":"C","text":"A DNS resolver that maps domain names to IP addresses"},{"label":"D","text":"A database connection pool manager"}]', 'B', 'A reverse proxy (such as NGINX or HAProxy) shields origin servers, handling SSL termination, compression, and request routing.', 10),
  ('What is Consistent Hashing commonly used for in distributed systems?', '[{"label":"A","text":"To encrypt user passwords in database tables"},{"label":"B","text":"To distribute keys across nodes in a distributed cache so that adding or removing a node re-maps only a minimal fraction of keys (K/N)"},{"label":"C","text":"To verify file checksums during downloads"},{"label":"D","text":"To authenticate JSON Web Tokens"}]', 'B', 'Consistent hashing maps keys and nodes onto a circular hash ring, preventing massive cache stampedes when cluster nodes scale.', 11),
  ('What is the purpose of the Circuit Breaker pattern in microservices?', '[{"label":"A","text":"To cut power to overheated server hardware"},{"label":"B","text":"To prevent an application from repeatedly invoking a failing remote service, avoiding cascading failures across the system"},{"label":"C","text":"To disconnect idle database connections after 30 seconds"},{"label":"D","text":"To block unauthorized IP addresses from visiting a website"}]', 'B', 'A circuit breaker trips when failure thresholds are exceeded, returning immediate fallbacks and allowing the troubled service time to recover.', 12),
  ('What does Idempotency mean in API and system design?', '[{"label":"A","text":"An operation that executes in under 1 millisecond"},{"label":"B","text":"An operation that can be applied multiple times without changing the result beyond the initial application"},{"label":"C","text":"An API endpoint that requires multi-factor authentication"},{"label":"D","text":"A database query that uses zero CPU resources"}]', 'B', 'An idempotent request (such as HTTP PUT or DELETE) can be safely retried without unintended side-effects (e.g. charging a card twice).', 13),
  ('What is the difference between Latency and Throughput?', '[{"label":"A","text":"Latency is the time taken to process a single request; Throughput is the number of requests processed per unit of time"},{"label":"B","text":"Latency is data size; Throughput is server uptime"},{"label":"C","text":"Throughput is measured in milliseconds; Latency is measured in requests/sec"},{"label":"D","text":"There is no difference"}]', 'A', 'Latency measures duration/delay (e.g. milliseconds); throughput measures volume/capacity (e.g. requests per second).', 14),
  ('What is a Database Read Replica used for?', '[{"label":"A","text":"Executing master write transactions exclusively"},{"label":"B","text":"Offloading read-heavy queries from the primary database to improve read scalability and performance"},{"label":"C","text":"Backing up deleted records permanently"},{"label":"D","text":"Generating SSL certificates"}]', 'B', 'Read replicas replicate data from the primary database asynchronously to handle read traffic without burdening the write primary.', 15),
  ('What is Cache Invalidation, and why is it notoriously challenging?', '[{"label":"A","text":"Purging dead connections; it is difficult due to hardware limits"},{"label":"B","text":"Ensuring cached data matches underlying source data when updates occur without serving stale data or causing cache stampedes"},{"label":"C","text":"Renewing SSL certificates before expiry"},{"label":"D","text":"Allocating memory addresses in C++"}]', 'B', 'Cache invalidation ensures cached copies are kept up to date or evicted when mutations occur, balancing freshness and performance.', 16),
  ('Which communication protocol establishes a persistent, full-duplex TCP connection between client and server?', '[{"label":"A","text":"HTTP/1.0"},{"label":"B","text":"WebSocket"},{"label":"C","text":"DNS"},{"label":"D","text":"SMTP"}]', 'B', 'WebSocket provides bidirectional, real-time communication over a single long-lived TCP connection.', 17),
  ('How does the Cache-Aside (Lazy Loading) caching pattern work?', '[{"label":"A","text":"The cache loads all database tables into RAM at system startup"},{"label":"B","text":"The application first checks the cache; on a cache miss, it reads from the database and populates the cache for subsequent reads"},{"label":"C","text":"The database writes to the cache in the background automatically"},{"label":"D","text":"Cache writes happen without writing to the database"}]', 'B', 'With Cache-Aside, the application code directly orchestrates reads from the cache and backfills misses from the primary data store.', 18),
  ('What is a Single Point of Failure (SPOF)?', '[{"label":"A","text":"A software bug that causes a 404 error"},{"label":"B","text":"A single component of a system that, if it ceases to function, will cause the entire system to fail"},{"label":"C","text":"An encryption key used by only one employee"},{"label":"D","text":"A network cable connected to one workstation"}]', 'B', 'A SPOF is any critical component whose lack of redundancy threatens the availability of the entire architecture.', 19),
  ('What is Rate Limiting used for in API design?', '[{"label":"A","text":"Slowing down all user requests to reduce CPU power bills"},{"label":"B","text":"Controlling the rate of incoming requests from clients to prevent abuse, DoS attacks, and resource starvation"},{"label":"C","text":"Limiting database row counts to 1,000 items"},{"label":"D","text":"Enforcing maximum password lengths"}]', 'B', 'Rate limiting constrains the frequency of requests a client can make within a given time window (e.g. 100 requests per minute).', 20),
  ('Which algorithm is commonly used for implementing API Rate Limiting?', '[{"label":"A","text":"Token Bucket / Leaky Bucket"},{"label":"B","text":"Dijkstra''s Shortest Path"},{"label":"C","text":"Binary Search"},{"label":"D","text":"Quicksort"}]', 'A', 'Token Bucket and Leaky Bucket algorithms track available request capacity over time with a constant refill rate.', 21),
  ('What is Eventual Consistency in distributed data stores?', '[{"label":"A","text":"Data will never be consistent across nodes"},{"label":"B","text":"A consistency model guaranteeing that if no new updates are made, all replicas will eventually return the latest value"},{"label":"C","text":"Writes are blocked until every node in the world confirms the write"},{"label":"D","text":"Data is erased every 24 hours"}]', 'B', 'Eventual consistency guarantees that all replicas will converge on identical states given sufficient time without new mutations.', 22),
  ('What is an API Gateway in a microservice architecture?', '[{"label":"A","text":"A firewall that blocks all HTTP connections"},{"label":"B","text":"A centralized reverse proxy service providing a single entry point for clients, handling routing, authentication, rate limiting, and telemetry"},{"label":"C","text":"A hardware router installed in an office server closet"},{"label":"D","text":"A database ORM tool"}]', 'B', 'An API Gateway simplifies client interactions by aggregating microservices, terminating auth, and directing traffic.', 23),
  ('What does SLA stand for in enterprise system infrastructure?', '[{"label":"A","text":"System Log Algorithm"},{"label":"B","text":"Service Level Agreement"},{"label":"C","text":"Server Load Architecture"},{"label":"D","text":"Software License Authorization"}]', 'B', 'An SLA is a formal commitment between a service provider and customer specifying metrics like uptime (e.g. 99.99%).', 24),
  ('What is Database Connection Pooling?', '[{"label":"A","text":"Opening a brand new database connection on every single HTTP request"},{"label":"B","text":"Maintaining a cache of open database connections that can be reused across incoming requests, avoiding connection setup latency"},{"label":"C","text":"Sharing database access with third-party partners publicly"},{"label":"D","text":"Combining SQL and NoSQL tables into one query"}]', 'B', 'Connection pooling avoids the significant overhead of handshaking new database connections for every query by reusing a warm pool.', 25),
  ('What is Distributed Tracing (such as with OpenTelemetry or Jaeger)?', '[{"label":"A","text":"Drawing network topology diagrams manually"},{"label":"B","text":"Tracking the end-to-end lifecycle and timing of requests as they flow across multiple distributed microservices using Correlation IDs"},{"label":"C","text":"Backtracking Git commits across repository branches"},{"label":"D","text":"Tracking physical delivery trucks via GPS"}]', 'B', 'Distributed tracing tracks requests through microservice boundaries using unique trace IDs to diagnose latency bottlenecks.', 26),
  ('When would you prefer a NoSQL document database (e.g. MongoDB) over a traditional relational SQL database?', '[{"label":"A","text":"When you require strict multi-table ACID transactions and normalized schemas"},{"label":"B","text":"When handling rapidly evolving, unstructured/polymorphic data models and needing horizontal scalability with flexible schemas"},{"label":"C","text":"When storing banking transaction ledgers exclusively"},{"label":"D","text":"When you have only 100 rows of static data"}]', 'B', 'Document stores excel with hierarchical, dynamic schemas that benefit from document-oriented access patterns and seamless horizontal sharding.', 27),
  ('What is a "Thundering Herd" (Cache Stampede) problem?', '[{"label":"A","text":"When thousands of simultaneous requests experience a cache miss for the same expired key and simultaneously overwhelm the database"},{"label":"B","text":"When too many developers push commits to master simultaneously"},{"label":"C","text":"When hard drives fill to 100% capacity"},{"label":"D","text":"When CSS animations consume excessive GPU cycles"}]', 'A', 'A cache stampede occurs when high concurrency causes many parallel cache misses to hit the database at once; mutex locks mitigate this.', 28),
  ('What is the purpose of Data Redundancy across different geographical availability zones?', '[{"label":"A","text":"Wasting disk storage to inflate infrastructure bills"},{"label":"B","text":"Ensuring disaster recovery, business continuity, and zero data loss if an entire data center experiences a catastrophic outage"},{"label":"C","text":"Speeding up code compilation times"},{"label":"D","text":"Translating English text into foreign languages"}]', 'B', 'Multi-AZ replication safeguards applications against localized disasters (power grid failure, earthquakes) ensuring high availability.', 29),
  ('What is Write-Behind (Write-Back) caching?', '[{"label":"A","text":"Writes are written directly to cache and immediately acknowledged; the cache asynchronously writes back to the database in batches"},{"label":"B","text":"Writes bypass cache completely and write directly to disk"},{"label":"C","text":"The database writes to the cache only after a 24-hour delay"},{"label":"D","text":"Cache updates are discarded if the network is busy"}]', 'A', 'Write-Back provides extremely low write latency by confirming writes as soon as they hit RAM cache, deferring database writes.', 30)
) AS q(question_text, options, correct_answer, explanation, q_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions qqs JOIN public.quizzes qz ON qqs.quiz_id = qz.id
  WHERE qz.skill_name = 'System Design' AND qqs.question_text = q.question_text
);

-- Notify PostgREST cache reload
NOTIFY pgrst, 'reload schema';
